# -*- coding: utf-8 -*-
"""SORUN_TAKIP.md içinde desen geçen kayıtların başlık + durum satırını (kısaltılmış) yazar. Kullanım: kayit_ara.py "desen1|desen2" [maks]"""
import re
import sys

sys.stdout.reconfigure(encoding='utf-8')
yol = r'C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb\ai_koordinasyon\SORUN_TAKIP.md'
desen = re.compile(sys.argv[1], re.I)
maks = int(sys.argv[2]) if len(sys.argv) > 2 else 40
satirlar = open(yol, encoding='utf-8').read().split('\n')
baslik = None
bas_no = 0
blok = []
bulunan = {}


def kapat():
    if baslik is not None and any(desen.search(s) for s in blok):
        bulunan[baslik] = (bas_no, blok[:])


for i, s in enumerate(satirlar, 1):
    if re.match(r'^## S-\d+', s):
        kapat()
        baslik, bas_no, blok = s, i, []
    else:
        blok.append(s)
kapat()
for b, (no, blk) in list(bulunan.items())[:maks]:
    print(f'[{no}] {b[:230]}')
    for s in blk[:2]:
        if s.strip():
            print('     ', s[:330])
print('toplam kayıt:', len(bulunan))

