# -*- coding: utf-8 -*-
"""'build_all.bat failed' ile reddedilen eski AST-x64 örneklerinin asıl (NASM/bağlayıcı) hata satırını bulur."""
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile

sys.stdout.reconfigure(encoding='utf-8')
KOK = r'C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb'
sp = r'C:\Users\mete\AppData\Local\Temp\claude\C--Users-mete-Downloads-BasicOyunSource-UXBc-Clean-UXBc-uxb\b85b832d-c86f-49e6-b0a0-47af736f8686\scratchpad'
uxb = os.path.join(KOK, 'bin', sys.argv[1])
d = json.load(open(sp + r'\gorunum\ornek_astx64_0253.json', encoding='utf-8'))
for x in d:
    if not (x['cikti'] and x['cikti'][0] == 'BUILDFAIL' and any('build_all.bat failed' in str(t) for t in x['cikti'])):
        continue
    p = os.path.join(KOK, x['dosya'].replace('/', os.sep))
    tmp = tempfile.mkdtemp(prefix='ba_')
    try:
        subprocess.run([uxb, 'bld', p, '--build-x64', '--x64-mode', 'AST', '--out-root', tmp], cwd=KOK, capture_output=True, timeout=200)
        ilk = []
        for dp, dn, fn in os.walk(tmp):
            for f in fn:
                if f == 'build_all.stderr.txt':
                    for s in open(os.path.join(dp, f), encoding='utf-8', errors='replace').read().splitlines():
                        if 'error' in s.lower() or 'undefined' in s.lower() or 'unresolved' in s.lower():
                            ilk.append(re.sub(r'^.*?x64_build[\\/]', '', s)[:160])
        tekil = []
        for s in ilk:
            if s not in tekil:
                tekil.append(s)
        print(x['dosya'].replace('docs/kitaplar/_ortak/ornekler/', ''))
        for s in tekil[:4]:
            print('      ', s)
        if len(tekil) > 4:
            print('       ... +', len(tekil) - 4, 'satır daha')
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

