# -*- coding: utf-8 -*-
"""WASM külliyat anlık görüntüleri (eski ↔ yeni) arasındaki değişimleri AST (0253) çıktısına göre sınıflar.
Kullanım: wasm_fark_sinifla.py eski_wasm.json yeni_wasm.json ast_goruntu.json [ayrinti]"""
import collections
import json
import re
import sys

sys.stdout.reconfigure(encoding="utf-8")
E = json.load(open(sys.argv[1], encoding="utf-8"))["vakalar"]
Y = json.load(open(sys.argv[2], encoding="utf-8"))["vakalar"]
A = json.load(open(sys.argv[3], encoding="utf-8"))["vakalar"]
ayrinti = len(sys.argv) > 4


def norm(c):
    return [x.strip() for x in c]


def durum(r):
    rc, c = r
    if rc == "DERLENMEDI":
        return "ret"
    return "kos" if rc == 0 else "hata"


sinif = collections.defaultdict(list)
for k in E:
    if "WASM" not in E[k] or "WASM" not in Y.get(k, {}):
        continue
    eski, yeni = E[k]["WASM"], Y[k]["WASM"]
    if eski == yeni:
        continue
    a = A.get(k, {}).get("AST")
    ast_ok = lambda r: a is not None and a[0] == 0 and r[0] == 0 and norm(r[1]) == norm(a[1])
    de, dy = durum(eski), durum(yeni)
    if de == "ret" and dy == "ret":
        ad = "ret → ret (ileti metni değişti)"
    elif de == "ret" and dy == "kos":
        ad = "ret → çalışır, AST ile AYNI (düzelme)" if ast_ok(yeni) else "ret → çalışır, AST'den FARKLI (açık ret → sessiz yanlış?)"
    elif de == "ret" and dy == "hata":
        ad = "ret → çalışma hatası"
    elif de == "kos" and dy == "ret":
        ad = "çalışır, AST ile aynıydı → ret (kapı sıkıldı: GERİLEME?)" if ast_ok(eski) else "çalışır, AST'den farklıydı → ret (sessiz yanlış kapandı)"
    elif de == "kos" and dy == "kos":
        if ast_ok(yeni) and not ast_ok(eski):
            ad = "çalışır → çalışır, yeni AST ile aynı (düzelme)"
        elif ast_ok(eski) and not ast_ok(yeni):
            ad = "çalışır → çalışır, ESKİ AST ile aynıydı (GERİLEME)"
        else:
            ad = "çalışır → çalışır, ikisi de AST'den farklı"
    else:
        ad = f"{de} → {dy}"
    sinif[ad].append((k, eski, yeni, a))
for ad, liste in sorted(sinif.items(), key=lambda t: -len(t[1])):
    print(f"{len(liste):4}  {ad}")
if ayrinti:
    for ad, liste in sorted(sinif.items(), key=lambda t: -len(t[1])):
        print("\n####", ad, len(liste))
        for k, eski, yeni, a in liste[:60]:
            print("-", k.split("::", 1)[0], "|", k.split("::", 1)[1][:60])
            print("    eski :", str(eski)[:170])
            print("    yeni :", str(yeni)[:170])
            if a is not None and ("FARKLI" in ad or "GERİLEME" in ad or "açık ret →" in ad):
                print("    AST  :", str(a)[:170])

