# -*- coding: utf-8 -*-
"""Seçilen sınıfın değişimlerini kodlarıyla gösterir. Kullanım: wasm_fark_goster.py eski.json yeni.json ast.json "sınıf alt dizesi" """
import json
import sys

sys.stdout.reconfigure(encoding="utf-8")
E = json.load(open(sys.argv[1], encoding="utf-8"))["vakalar"]
Y = json.load(open(sys.argv[2], encoding="utf-8"))["vakalar"]
A = json.load(open(sys.argv[3], encoding="utf-8"))["vakalar"]
istek = sys.argv[4]


def norm(c):
    return [x.strip() for x in c]


def durum(r):
    rc, c = r
    return "ret" if rc == "DERLENMEDI" else ("kos" if rc == 0 else "hata")


for k in E:
    if "WASM" not in E[k] or "WASM" not in Y.get(k, {}):
        continue
    eski, yeni = E[k]["WASM"], Y[k]["WASM"]
    if eski == yeni:
        continue
    a = A.get(k, {}).get("AST")
    ok = lambda r: a is not None and a[0] == 0 and r[0] == 0 and norm(r[1]) == norm(a[1])
    de, dy = durum(eski), durum(yeni)
    if istek == "ret_kos_farkli" and de == "ret" and dy == "kos" and not ok(yeni):
        pass
    elif istek == "kos_kos_farkli" and de == "kos" and dy == "kos" and not ok(yeni):
        pass
    elif istek == "kos_kos_duzelme" and de == "kos" and dy == "kos" and ok(yeni):
        pass
    elif istek == "ret_kos_ayni" and de == "ret" and dy == "kos" and ok(yeni):
        pass
    elif istek == "kos_ret_farkli" and de == "kos" and dy == "ret" and not ok(eski):
        pass
    else:
        continue
    print("=" * 6, k.split("::", 1)[0], "|", k.split("::", 1)[1][:70])
    print("  kod  :", E[k]["kod"].replace("\n", " ⏎ ")[:330])
    print("  eski :", str(eski)[:200])
    print("  yeni :", str(yeni)[:200])
    print("  AST  :", str(a)[:200])

