# -*- coding: utf-8 -*-
"""Klasör boyut/yaş envanteri (salt okunur). Kullanım: boyut_tara.py kök [cikti.json]
Her doğrudan alt klasör için: toplam bayt, dosya sayısı, en yeni ve en eski değişiklik zamanı, en büyük 3 dosya. Kökteki dosyalar ayrıca toplanır."""
import json
import os
import sys
import time

sys.stdout.reconfigure(encoding="utf-8")
kok = sys.argv[1]
cikti = sys.argv[2] if len(sys.argv) > 2 else None


def tara(yol):
    toplam = 0
    adet = 0
    yeni = 0.0
    eski = 1e18
    buyuk = []
    yiginlar = [yol]
    while yiginlar:
        d = yiginlar.pop()
        try:
            with os.scandir(d) as it:
                for e in it:
                    try:
                        if e.is_symlink():
                            continue
                        if e.is_dir(follow_symlinks=False):
                            yiginlar.append(e.path)
                        else:
                            st = e.stat(follow_symlinks=False)
                            toplam += st.st_size
                            adet += 1
                            yeni = max(yeni, st.st_mtime)
                            eski = min(eski, st.st_mtime)
                            if st.st_size > 20 * 1024 * 1024:
                                buyuk.append((st.st_size, e.path))
                    except OSError:
                        pass
        except OSError:
            pass
    buyuk.sort(reverse=True)
    return {"bayt": toplam, "adet": adet, "yeni": yeni, "eski": eski if adet else 0, "buyuk": buyuk[:3]}


sonuc = {}
kokdosya = {"bayt": 0, "adet": 0}
t0 = time.time()
with os.scandir(kok) as it:
    for e in sorted(it, key=lambda x: x.name.lower()):
        if e.is_symlink():
            continue
        if e.is_dir(follow_symlinks=False):
            sonuc[e.name] = tara(e.path)
        else:
            try:
                kokdosya["bayt"] += e.stat().st_size
                kokdosya["adet"] += 1
            except OSError:
                pass
sonuc["<kök dosyaları>"] = {"bayt": kokdosya["bayt"], "adet": kokdosya["adet"], "yeni": 0, "eski": 0, "buyuk": []}
if cikti:
    json.dump(sonuc, open(cikti, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
zam = lambda t: time.strftime("%Y-%m-%d", time.localtime(t)) if t else "-"
print(f"kök: {kok}  (tarama {time.time() - t0:.0f} sn)")
print(f"{'klasör':44} {'MB':>9} {'dosya':>8}  {'en yeni':10} {'en eski':10}")
for ad, v in sorted(sonuc.items(), key=lambda kv: -kv[1]["bayt"]):
    print(f"{ad[:44]:44} {v['bayt'] / 1048576:9.1f} {v['adet']:8}  {zam(v['yeni']):10} {zam(v['eski']):10}")
print(f"TOPLAM {sum(v['bayt'] for v in sonuc.values()) / 1073741824:.2f} GB")

