"""Bir klasörün doğrudan alt klasörlerini (ve en büyük dosyalarını) boyutla listeler (salt okunur). Kullanım: boyut_derin.py klasör [ilk_n]"""
import os
import sys
import time

sys.stdout.reconfigure(encoding="utf-8")
kok = sys.argv[1]
n = int(sys.argv[2]) if len(sys.argv) > 2 else 20


def tara(yol):
    toplam = adet = 0
    yeni, eski = 0.0, 1e18
    yig = [yol]
    while yig:
        d = yig.pop()
        try:
            with os.scandir(d) as it:
                for e in it:
                    try:
                        if e.is_symlink():
                            continue
                        if e.is_dir(follow_symlinks=False):
                            yig.append(e.path)
                        else:
                            st = e.stat(follow_symlinks=False)
                            toplam += st.st_size
                            adet += 1
                            yeni = max(yeni, st.st_mtime)
                            eski = min(eski, st.st_mtime)
                    except OSError:
                        pass
        except OSError:
            pass
    return toplam, adet, yeni, (eski if adet else 0)


zam = lambda t: time.strftime("%Y-%m-%d", time.localtime(t)) if t else "-"
satir = []
dosyalar = []
with os.scandir(kok) as it:
    for e in it:
        if e.is_symlink():
            continue
        if e.is_dir(follow_symlinks=False):
            b, a, y, es = tara(e.path)
            satir.append((b, e.name, a, y, es))
        else:
            try:
                dosyalar.append((e.stat().st_size, e.name, e.stat().st_mtime))
            except OSError:
                pass
satir.sort(reverse=True)
dosyalar.sort(reverse=True)
print(f"== {kok}")
print(f"{'alt klasör':52} {'MB':>9} {'dosya':>8}  {'en yeni':10} {'en eski':10}")
for b, ad, a, y, es in satir[:n]:
    print(f"{ad[:52]:52} {b / 1048576:9.1f} {a:8}  {zam(y):10} {zam(es):10}")
print(f"(alt klasör sayısı: {len(satir)}; toplam {sum(s[0] for s in satir) / 1073741824:.2f} GB)")
print("-- kökteki en büyük dosyalar")
for b, ad, t in dosyalar[:n]:
    print(f"{ad[:60]:60} {b / 1048576:9.1f} MB  {zam(t)}")
print(f"(kök dosyaları: {len(dosyalar)} adet, {sum(d[0] for d in dosyalar) / 1048576:.1f} MB)")

