"""reports\\ altındaki .dll / .exe / .obj dosyalarının kaç tanesinin yalnızca kopya olduğunu ölçer (salt okunur).
Kopya ölçütü: aynı ad + aynı boyut. Ayrıca bin\\ ve dist\\ altında aynı ad+boyutta bir özgün var mı bakar."""
import collections
import hashlib
import os
import sys

sys.stdout.reconfigure(encoding="utf-8")
UXB = r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb"
KOK = os.path.join(UXB, "reports")
EK = {".dll", ".exe", ".obj"}

grup = collections.defaultdict(list)  # (ad, boyut, ek) -> yollar
for yol, _a, dosyalar in os.walk(KOK):
    for d in dosyalar:
        e = os.path.splitext(d)[1].lower()
        if e in EK:
            p = os.path.join(yol, d)
            try:
                grup[(d.lower(), os.path.getsize(p), e)].append(p)
            except OSError:
                pass

# özgün kaynaklar: bin\ ve dist\ ve tmp\ altındaki dll/exe ad+boyut kümesi
ozgun = set()
for taban in ("bin", "dist", "tmp", "native", "runtime_ext"):
    for yol, _a, dosyalar in os.walk(os.path.join(UXB, taban)):
        for d in dosyalar:
            if os.path.splitext(d)[1].lower() in EK:
                try:
                    ozgun.add((d.lower(), os.path.getsize(os.path.join(yol, d))))
                except OSError:
                    pass

for e in (".dll", ".exe", ".obj"):
    anahtarlar = [k for k in grup if k[2] == e]
    dosya = sum(len(grup[k]) for k in anahtarlar)
    mb = sum(k[1] * len(grup[k]) for k in anahtarlar) / 1048576
    tek = sum(k[1] * (len(grup[k]) - 1) for k in anahtarlar) / 1048576  # her gruptan biri kalsa kopya olan kısım
    ozgun_var = sum(len(grup[k]) for k in anahtarlar if (k[0], k[1]) in ozgun)
    ozgun_mb = sum(k[1] * len(grup[k]) for k in anahtarlar if (k[0], k[1]) in ozgun) / 1048576
    print(f"{e}: {dosya} dosya, {mb:,.0f} MB · benzersiz (ad+boyut) {len(anahtarlar)} · kopya payı {tek:,.0f} MB · "
          f"bin/dist/tmp'de aynı ad+boyutlu özgünü olan {ozgun_var} dosya ({ozgun_mb:,.0f} MB)")

print("== .dll: en çok tekrar eden 12 (ad, boyut MB, adet, bin/dist/tmp'de özgünü var mı)")
dll = sorted(((len(v), k) for k, v in grup.items() if k[2] == ".dll"), reverse=True)[:12]
for adet, k in dll:
    print(f"  {adet:6} x {k[0]:34} {k[1] / 1048576:7.2f} MB  özgün: {'evet' if (k[0], k[1]) in ozgun else 'HAYIR'}")

print("== .dll: adı+boyutu tek olan (tek kopya, kaybolursa başka yerde yok olabilir) ilk 12")
tekler = [(k, v[0]) for k, v in grup.items() if k[2] == ".dll" and len(v) == 1 and (k[0], k[1]) not in ozgun]
print("  sayı:", len(tekler), " toplam MB:", round(sum(k[1] for k, _ in tekler) / 1048576))
for k, p in sorted(tekler, key=lambda x: -x[0][1])[:12]:
    print(f"  {k[1] / 1048576:7.2f} MB  {os.path.relpath(p, KOK)}")

