ozgun = collections.defaultdict(list)
for sira, taban in enumerate(OZGUN_KOKLERI):
    for yol, _a, dosyalar in os.walk(os.path.join(UXB, taban)):
        for d in dosyalar:
            if d.lower().endswith(".dll"):
                p = os.path.join(yol, d)
                try:
                    ozgun[(d.lower(), os.path.getsize(p))].append(p)
                except OSError:
                    pass
print(f"özgün dizini: {len(ozgun)} (ad,boyut) anahtarı · {time.time() - t0:.0f} sn", flush=True)

# 2) aday kopyalar
adaylar = []
for yol, _a, dosyalar in os.walk(REPORTS):
    for d in dosyalar:
        if d.lower().endswith(".dll"):
            p = os.path.join(yol, d)
            try:
                b = os.path.getsize(p)
            except OSError:
                continue
            if (d.lower(), b) in ozgun:
                adaylar.append((p, b, (d.lower(), b)))
print(f"ad+boyutu özgünle eşleşen aday: {len(adaylar)} dosya · {sum(a[1] for a in adaylar) / 1073741824:.2f} GB · {time.time() - t0:.0f} sn", flush=True)

# 3) özgünlerin sha256'ları (yalnız gereken anahtarlar için, ilk özgün yeter ama hepsini hesapla: hepsi aynı mı görülsün)
ozgun_sha = {}
gerekli = {a[2] for a in adaylar}
yollar = [(k, p) for k in gerekli for p in ozgun[k]]
with ThreadPoolExecutor(IS_PARCACIGI) as ex:
    for (k, p), h in zip(yollar, ex.map(lambda kp: sha(kp[1]), yollar)):
        ozgun_sha.setdefault(k, {})[h] = p  # hash -> özgün yol (aynı hash'li ilk yol kalır)
print(f"özgün sha256 hesaplandı: {len(yollar)} dosya · {time.time() - t0:.0f} sn", flush=True)

# 4) adayların sha256'sı ve karşılaştırma
dogrulanan, uyusmayan = [], []


def isle(a):
    p, b, k = a
    try:
        h = sha(p)
    except OSError as e:
        return (p, b, k, None, str(e))
    return (p, b, k, h, None)


bitti = 0
with ThreadPoolExecutor(IS_PARCACIGI) as ex:
    for p, b, k, h, hata in ex.map(isle, adaylar, chunksize=1):
        bitti += 1
        if bitti % 2500 == 0:
            print(f"  {bitti}/{len(adaylar)} · {time.time() - t0:.0f} sn", flush=True)
        if hata:
            uyusmayan.append((p, b, "okunamadı: " + hata))
        elif h in ozgun_sha[k]:
            dogrulanan.append((p, b, h, ozgun_sha[k][h]))
        else:
            uyusmayan.append((p, b, "sha256 farklı (özgünle aynı ad+boyut ama farklı içerik)"))

topla = lambda l: sum(x[1] for x in l) / 1073741824
print("== SONUÇ")
print(f"  SHA-256 ile özgünüyle birebir aynı (silinebilir kopya): {len(dogrulanan)} dosya · {topla(dogrulanan):.2f} GB")
print(f"  doğrulanamayan (DOKUNULMAZ): {len(uyusmayan)} dosya · {topla(uyusmayan):.2f} GB")
for p, b, neden in uyusmayan[:10]:
    print("    ", os.path.relpath(p, REPORTS), "|", neden)

konum = collections.Counter()
konum_gb = collections.Counter()
for p, b, h, o in dogrulanan:
    ust = os.path.relpath(o, UXB).split(os.sep)[0]
    konum[ust] += 1
    konum_gb[ust] += b
print("  özgün konumları (hangi kalıcı klasörde duruyor):", {k: f"{v} dosya / {konum_gb[k] / 1073741824:.2f} GB" for k, v in konum.items()})

with open(CIKTI_TSV, "w", encoding="utf-8", newline="") as f:
    f.write("kopya_yolu\tboyut_bayt\tsha256\tozgun_yolu\n")
    for p, b, h, o in sorted(dogrulanan):
        f.write(f"{os.path.relpath(p, UXB)}\t{b}\t{h}\t{os.path.relpath(o, UXB)}\n")
print(f"  denetim izi yazıldı: {CIKTI_TSV} · toplam süre {time.time() - t0:.0f} sn")

