# -*- coding: utf-8 -*-
"""SORUN_TAKIP.md kayıtlarına DURUMU DEĞİŞTİRMEDEN 'Güncelleme' satırı ekler.
Kullanım (başka betikten): import not_ekle; not_ekle.ekle({"S-123": "metin", ...}[, durum_degis={"S-9": "YAPILDI"}])"""
import os, re, sys
sys.stdout.reconfigure(encoding="utf-8")
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import durum_guncelle

TAKIP = durum_guncelle.TAKIP


def mevcut_durum(no):
    satirlar = open(TAKIP, "rb").read().decode("utf-8").split("\n")
    bas = next((i for i, s in enumerate(satirlar) if re.match(rf"^## {re.escape(no)}\b", s.rstrip("\r"))), None)
    if bas is None:
        return None
    for i in range(bas + 1, min(bas + 6, len(satirlar))):
        m = re.search(r"\*\*Durum:\*\*\s*`([^`]+)`", satirlar[i])
        if m:
            return m.group(1)
    return None


def ekle(notlar, durum_degis=None):
    durum_degis = durum_degis or {}
    U = {}
    for no, metin in notlar.items():
        d = durum_degis.get(no) or mevcut_durum(no)
        if d is None:
            print("durum bulunamadı, atlandı:", no)
            continue
        U[no] = (d, metin)
    durum_guncelle.uygula(U)


def s_no(g_kimlik):
    """veri/sorun_eslemesi.txt: G-kaydı -> S-numarası."""
    yol = os.path.join(r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb\tools\kitap\kilavuz_v2\veri", "sorun_eslemesi.txt")
    for s in open(yol, encoding="utf-8").read().splitlines():
        m = re.fullmatch(r"\s*(G-[A-ZÇĞİÖŞÜ]+-\d+)\s*=\s*(S-\d+)\s*", s)
        if m and m.group(1) == g_kimlik:
            return m.group(2)
    return None

