# -*- coding: utf-8 -*-
"""KADEME 1 (Mete onayı: 2026-10-15): reports içindeki çalışma DLL kopyalarını DOĞRULA-VE-SİL.
Güvenceler:
  * yalnızca kopya_dll_aday.tsv'deki dosyalar (önceki salt okunur denemede SHA-256 ile özgünüyle aynı bulunmuşlar);
  * her dosya silinmeden hemen önce yeniden SHA-256 hesaplanır: TSV'deki değere VE özgünün şimdiki SHA-256'sına eşit olmalı;
  * özgün yoksa/değişmişse o özgüne bağlı kopyalara dokunulmaz;
  * son 48 saatte oluşturulmuş/değişmiş dosyalar atlanır (canlı koşular);
  * yalnızca .dll; hiçbir klasör, zip, json, log silinmez.
Çıktı: özet + silinenler.tsv (scratchpad)."""
import hashlib
import os
import shutil
import sys
import time
from concurrent.futures import ThreadPoolExecutor

sys.stdout.reconfigure(encoding="utf-8")
UXB = r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb"
SP = os.path.dirname(os.path.abspath(__file__))
TSV = os.path.join(SP, "kopya_dll_aday.tsv")
LOG = os.path.join(SP, "silinenler.tsv")
IS = 4
SIMDI = time.time()
KORUMA_SN = 48 * 3600
t0 = time.time()


def uzun(p):
    return "\\\\?\\" + p if not p.startswith("\\\\?\\") else p


def sha(p):
    h = hashlib.sha256()
    with open(uzun(p), "rb") as f:
        while True:
            b = f.read(4 * 1024 * 1024)
            if not b:
                break
            h.update(b)
    return h.hexdigest()


def bos_gb():
    return shutil.disk_usage("C:\\").free / 1073741824


satirlar = open(TSV, encoding="utf-8").read().splitlines()[1:]
kayit = []
for s in satirlar:
    yol, boyut, hsh, ozgun = s.split("\t")
    kayit.append((yol, int(boyut), hsh, ozgun))
print(f"aday: {len(kayit)} dosya · {sum(k[1] for k in kayit) / 1073741824:.2f} GB · C: boş (önce) {bos_gb():.2f} GB", flush=True)

# 1) özgünlerin şimdiki SHA-256'sı
ozgunler = sorted({k[3] for k in kayit})
ozgun_ok = {}


def ozgun_kontrol(o):
    p = os.path.join(UXB, o)
    if not os.path.isfile(uzun(p)):
        return o, None
    return o, sha(p)


with ThreadPoolExecutor(IS) as ex:
    for o, h in ex.map(ozgun_kontrol, ozgunler):
        ozgun_ok[o] = h
print(f"özgün: {len(ozgunler)} dosya doğrulandı · yok/okunamayan: {sum(1 for v in ozgun_ok.values() if v is None)} · {time.time() - t0:.0f} sn", flush=True)

sayac = {"silindi": 0, "ozgun_degisti_yok": 0, "yok": 0, "boyut_farkli": 0, "yeni_dosya_atlandi": 0, "hash_farkli": 0, "silinemedi": 0}
bayt = {"silindi": 0}
silinen = []


def isle(k):
    yol, boyut, hsh, ozgun = k
    p = os.path.join(UXB, yol)
    if not yol.lower().startswith("reports\\") or not yol.lower().endswith(".dll"):
        return ("hash_farkli", k, "yol ilkesine aykırı")  # asla olmamalı; güvenlik ağı
    og = ozgun_ok.get(ozgun)
    if og is None or og != hsh:
        return ("ozgun_degisti_yok", k, "")
    try:
        st = os.stat(uzun(p))
    except OSError:
        return ("yok", k, "")
    if st.st_size != boyut:
        return ("boyut_farkli", k, "")
    if SIMDI - st.st_mtime < KORUMA_SN or SIMDI - st.st_ctime < KORUMA_SN:
        return ("yeni_dosya_atlandi", k, "")
    try:
        h = sha(p)
    except OSError as e:
        return ("silinemedi", k, "okunamadı: " + str(e))
    if h != hsh:
        return ("hash_farkli", k, "")
    try:
        os.remove(uzun(p))
    except OSError as e:
        return ("silinemedi", k, str(e))
    return ("silindi", k, "")


bitti = 0
with open(LOG, "w", encoding="utf-8", newline="\n") as lg:
    lg.write("yol\tboyut\tsha256_ilk16\tozgun\n")
    with ThreadPoolExecutor(IS) as ex:
        for sonuc, k, not_ in ex.map(isle, kayit, chunksize=1):
            sayac[sonuc] += 1
            if sonuc == "silindi":
                bayt["silindi"] += k[1]
                lg.write(f"{k[0]}\t{k[1]}\t{k[2][:16]}\t{k[3]}\n")
            elif sonuc in ("silinemedi", "hash_farkli"):
                print("  !", sonuc, k[0], not_, flush=True)
            bitti += 1
            if bitti % 2500 == 0:
                print(f"  {bitti}/{len(kayit)} · silinen {sayac['silindi']} · {bayt['silindi'] / 1073741824:.2f} GB · {time.time() - t0:.0f} sn", flush=True)

print("== SONUÇ")
for ad, n in sayac.items():
    print(f"  {ad}: {n}")
print(f"  silinen toplam: {bayt['silindi'] / 1073741824:.2f} GB · C: boş (sonra) {bos_gb():.2f} GB · süre {time.time() - t0:.0f} sn")
# özgünler sağlam mı (son denetim)
bozuk = 0
for o in ozgunler:
    p = os.path.join(UXB, o)
    if not os.path.isfile(uzun(p)):
        bozuk += 1
print(f"  özgün dosyaların varlığı: {len(ozgunler) - bozuk}/{len(ozgunler)}")

