    ev, yv = E["vakalar"], Y["vakalar"]
    ortak = [k for k in ev if k in yv]
    print(f"ortak vaka: {len(ortak)}; yalnız eskide: {len(set(ev) - set(yv))}; yalnız yenide: {len(set(yv) - set(ev))}")
