                kisalt = (lambda x: (str(x)[:230] + "…") if len(str(x)) > 230 else str(x))
                print(f"    {m:<4} eski: {kisalt(o)}")
                print(f"    {'':<4} yeni: {kisalt(n)}")
            if a.tam:
