# -*- coding: utf-8 -*-
"""Katı kural ("ileri kullanım için DECLARE zorunlu") kaç programı etkilerdi? Kaynak metin sezgisiyle, salt okunur.
Bir program 'etkilenir' = bir SUB/FUNCTION çağrısı, tanımından ÖNCE geçer ve o ad için DECLARE satırı yoktur."""
import os
import re
import sys

sys.stdout.reconfigure(encoding="utf-8")
KOK = r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb"
TANIM = re.compile(r"^\s*(?:PRIVATE\s+|PUBLIC\s+|STATIC\s+)*(SUB|FUNCTION)\s+([A-Za-z_][A-Za-z0-9_]*)\s*\(", re.I)
DECL = re.compile(r"^\s*DECLARE\s+(SUB|FUNCTION)\s+([A-Za-z_][A-Za-z0-9_]*)", re.I)


def incele(metin):
    satirlar = metin.replace("\r\n", "\n").split("\n")
    tanim_satiri = {}
    declare = set()
    for i, s in enumerate(satirlar):
        s0 = s.split("'")[0]
        m = TANIM.match(s0)
        if m and not DECL.match(s0):
            tanim_satiri.setdefault(m.group(2).lower(), i)
        d = DECL.match(s0)
        if d:
            declare.add(d.group(2).lower())
    if not tanim_satiri:
        return None  # rutin tanımı yok
    etkilenen = []
    for ad, ti in tanim_satiri.items():
        rx = re.compile(r"(?<![A-Za-z0-9_.])" + re.escape(ad) + r"\s*\(", re.I)
        for i in range(0, ti):
            s0 = satirlar[i].split("'")[0]
            if TANIM.match(s0) or DECL.match(s0):
                continue
            if rx.search(s0):
                if ad not in declare:
                    etkilenen.append(ad)
                break
    return etkilenen


def tara(klasor, uzanti=".uxb"):
    toplam = rutinli = etkilenen = 0
    ornek = []
    for kok, _a, ds in os.walk(klasor):
        for d in ds:
            if not d.lower().endswith(uzanti):
                continue
            try:
                m = open(os.path.join(kok, d), encoding="utf-8", errors="replace").read()
