# -*- coding: utf-8 -*-
"""Bir klasörün dosyalarının, verilen zip'lerin içeriğiyle (boyut + CRC32) örtüşüp örtüşmediğini ölçer (SALT OKUNUR).
Kullanım: zip_dogrula.py <klasor> <zip_klasoru_veya_zip> [<zip> ...]
Çıktı: örtülen / örtülmeyen dosya sayısı ve boyutu; örtülmeyenlerin ilk 15'i."""
import os
import sys
import zipfile
import zlib

sys.stdout.reconfigure(encoding="utf-8")
klasor = sys.argv[1]
zipler = []
for y in sys.argv[2:]:
    if os.path.isdir(y):
        zipler += [os.path.join(y, d) for d in os.listdir(y) if d.lower().endswith(".zip")]
    else:
        zipler.append(y)
anahtar = set()
for z in zipler:
    try:
        with zipfile.ZipFile(z) as zf:
            for i in zf.infolist():
                if not i.is_dir():
                    anahtar.add((i.file_size, i.CRC))
        print("zip okundu:", os.path.basename(z), "·", os.path.getsize(z) // 1048576, "MB")
    except Exception as e:  # noqa: BLE001
        print("zip okunamadı:", z, e)


def crc(p):
    c = 0
    with open(p, "rb") as f:
        while True:
            b = f.read(4 * 1024 * 1024)
            if not b:
                break
            c = zlib.crc32(b, c)
    return c & 0xFFFFFFFF


orto = []
disi = []
for kok, _a, ds in os.walk(klasor):
    for d in ds:
        p = os.path.join(kok, d)
        try:
            b = os.path.getsize(p)
            if (b, crc(p)) in anahtar:
                orto.append((p, b))
            else:
                disi.append((p, b))
        except OSError as e:
            disi.append((p, -1))
print(f"== {klasor}")
print(f"  zip'lerle örtülen: {len(orto)} dosya, {sum(b for _, b in orto) / 1048576:.1f} MB")
print(f"  örtülmeyen:        {len(disi)} dosya, {sum(max(b, 0) for _, b in disi) / 1048576:.1f} MB")
for p, b in sorted(disi, key=lambda x: -x[1])[:15]:
    print(f"    {b / 1048576:8.2f} MB  {os.path.relpath(p, klasor)}")

