            satir.append(f"{ad}×{len(ds)} (örn. {ds[0][:4]}…, uzunluk {len(ds[0])})")
        print(f"  {f}\n      " + "; ".join(satir))
    print("desen toplamları:", ozet)
    return toplam


def temizle(kaynak, hedef):
    sayi_d = sayi_g = 0
    for kok, _a, ds in os.walk(kaynak):
        for d in ds:
            s = os.path.join(kok, d)
            r = os.path.relpath(s, kaynak)
