# -*- coding: utf-8 -*-
"""Gizli anahtar/parola tarayıcı ve temizleyici (yerel; hiçbir şey dışarı gönderilmez).

  python gizli_tara.py tara  <yol> [<yol> ...]            -> dosya başına desen sayıları (önizleme maskeli)
  python gizli_tara.py temizle <kaynak_klasor> <hedef_klasor>  -> kaynak ağacını hedefe kopyalar; bulunan gizli değerleri
                                                              [GIZLI-SILINDI:<desen>] ile değiştirir (kaynak değişmez)
Maske: değerin yalnız ilk 4 karakteri gösterilir.
İkili dosyalar (ilk 8 KB'de NUL) taranmaz/kopyalanmaz değişmeden aktarılır."""
import math
import os
import re
import shutil
import sys

sys.stdout.reconfigure(encoding="utf-8")

# (ad, regex, grup) — grup: gizli değerin yakalandığı grup (0 = tüm eşleşme)
DESENLER = [
    ("anthropic", re.compile(r"sk-ant-[A-Za-z0-9_\-]{20,}"), 0),
    ("openrouter", re.compile(r"sk-or-v1-[A-Za-z0-9]{20,}"), 0),
    ("sk_anahtar", re.compile(r"\bsk-[A-Za-z0-9]{32,}"), 0),
    ("google_aiza", re.compile(r"AIza[0-9A-Za-z_\-]{35}"), 0),
    ("github_token", re.compile(r"\bgh[pousr]_[A-Za-z0-9]{36,}"), 0),
    ("github_pat", re.compile(r"github_pat_[A-Za-z0-9_]{50,}"), 0),
    ("groq", re.compile(r"\bgsk_[A-Za-z0-9]{40,}"), 0),
    ("slack", re.compile(r"\bxox[abprs]-[A-Za-z0-9\-]{10,}"), 0),
    ("aws", re.compile(r"\bAKIA[0-9A-Z]{16}\b"), 0),
    ("ozel_anahtar_blogu", re.compile(r"-----BEGIN (?:RSA |EC |DSA |OPENSSH |PGP )?PRIVATE KEY-----[\s\S]{0,4000}?-----END (?:RSA |EC |DSA |OPENSSH |PGP )?PRIVATE KEY-----"), 0),
    ("jwt", re.compile(r"\beyJ[A-Za-z0-9_\-]{15,}\.eyJ[A-Za-z0-9_\-]{15,}\.[A-Za-z0-9_\-]{10,}"), 0),
    ("bearer", re.compile(r"\bBearer\s+([A-Za-z0-9._\-]{30,})"), 1),
    ("atama", re.compile(r"(?i)\b(?:api[_\-]?key|apikey|secret(?:[_\-]?key)?|access[_\-]?token|refresh[_\-]?token|auth[_\-]?token|passwd|password|authorization)\b[\"']?\s*[:=]\s*[\"']?([A-Za-z0-9_\-\.+/=]{24,})"), 1),
    # ---- 2026-10-15: GitHub itirak koruması bir Google "AQ." anahtarını yakaladı, ilk tarayıcı kaçırmıştı -> desenler genişletildi
    ("google_aq", re.compile(r"\bAQ\.[A-Za-z0-9_\-]{30,}"), 0),
    ("google_oauth", re.compile(r"\bya29\.[A-Za-z0-9_\-]{20,}|\b1//0[A-Za-z0-9_\-]{30,}|\bGOCSPX-[A-Za-z0-9_\-]{20,}"), 0),
    ("sk_proje", re.compile(r"\bsk-(?:proj|svcacct|admin)-[A-Za-z0-9_\-]{30,}"), 0),
    ("sk_uzun", re.compile(r"\bsk-[A-Za-z0-9_\-]{40,}"), 0),
    ("hizmet_belirteci", re.compile(r"\b(?:hf_[A-Za-z0-9]{30,}|r8_[A-Za-z0-9]{30,}|pplx-[A-Za-z0-9]{30,}|xai-[A-Za-z0-9]{40,}|nvapi-[A-Za-z0-9_\-]{40,}|glpat-[A-Za-z0-9_\-]{20,}|npm_[A-Za-z0-9]{30,}|dop_v1_[a-f0-9]{40,}|shpat_[a-f0-9]{30,}|SG\.[A-Za-z0-9_\-]{20,}\.[A-Za-z0-9_\-]{20,})"), 0),
    # ORTAM DEĞİŞKENİ ATAMASI: ..._KEY / ..._TOKEN / ..._SECRET / ..._PASSWORD = değer (JSON kaçışlı \n, tırnak, boşluk, virgülde biter)
    ("ortam_anahtari", re.compile(r"(?i)\b[A-Z][A-Z0-9_]*(?:API[_\-]?KEY|ACCESS[_\-]?KEY|SECRET[_\-]?KEY|AUTH[_\-]?TOKEN|ACCESS[_\-]?TOKEN|_KEY|_TOKEN|_SECRET|_PASSWORD|_PASSWD)\b[\"']?[ \t]*=[ \t]*[\"']?([^\s\"'\\,;<>$%{}\[\]()]{12,})"), 1),
    ("url_anahtar", re.compile(r"(?i)[?&](?:key|api_key|apikey|access_token|token)=([A-Za-z0-9_\-\.]{16,})"), 1),
    ("baglanti_parolasi", re.compile(r"\b[a-z][a-z0-9+.\-]{2,}://[^/\s:@\"'\\]+:([^@\s\"'/\\]{4,})@"), 1),
    ("basic_yetki", re.compile(r"\bBasic\s+([A-Za-z0-9+/=]{20,})"), 1),
]
ORTAM_YER_TUTUCU = re.compile(r"(?i)^(?:your|xxx|dummy|example|changeme|change-this|placeholder|redacted|none|null|true|false|\.\.\.)")
YER_TUTUCU = re.compile(r"(?i)change|example|your|xxx|placeholder|dummy|sample|<|>|\$\{|%[A-Za-z_]+%|\.\.\.|test|fake|redacted|gizli|ornek|örnek|\bnone\b|\bnull\b|^[a-z]+$")


def entropi(s):
    if not s:
        return 0.0
    sy = {}
    for c in s:
        sy[c] = sy.get(c, 0) + 1
    return -sum(v / len(s) * math.log2(v / len(s)) for v in sy.values())


def gecerli(ad, deger):
    if ad == "ortam_anahtari":
        return not ORTAM_YER_TUTUCU.search(deger) and any(c.isalpha() for c in deger) and (any(c.isdigit() for c in deger) or len(deger) >= 20)
    if ad in ("url_anahtar", "baglanti_parolasi", "basic_yetki"):
        return not ORTAM_YER_TUTUCU.search(deger) and entropi(deger) >= 3.0
    if ad == "atama":
        if YER_TUTUCU.search(deger):
            return False
        return entropi(deger) >= 3.6 and any(c.isdigit() for c in deger) and any(c.isalpha() for c in deger)
    if ad == "bearer":
        return not YER_TUTUCU.search(deger) and entropi(deger) >= 3.4
    return True


def ikili_mi(veri):
    return b"\0" in veri[:8192]


def tara_metin(metin):
    """-> [(ad, baslangic, bitis, deger)]"""
    bulunan = []
    for ad, rx, g in DESENLER:
        for m in rx.finditer(metin):
            deger = m.group(g)
            if gecerli(ad, deger):
                bulunan.append((ad, m.start(g), m.end(g), deger))
    # örtüşenleri ayıkla: başlangıca göre sırala, aynı yerde en uzun kalsın; öncekiyle örtüşen atlanır
    bulunan.sort(key=lambda x: (x[1], -(x[2] - x[1])))
    temiz, son = [], -1
    for b in bulunan:
        if b[1] >= son:
            temiz.append(b)
            son = b[2]
    return temiz


def dosyalar(yol):
    if os.path.isfile(yol):
        yield yol
        return
    for kok, _a, ds in os.walk(yol):
        for d in ds:
            yield os.path.join(kok, d)


def tara(yollar):
    toplam = {}
    dosya_say = 0
    for y in yollar:
        for f in dosyalar(y):
            try:
                if os.path.getsize(f) > 400 * 1024 * 1024:
                    continue
                veri = open(f, "rb").read()
            except OSError:
                continue
            if ikili_mi(veri):
                continue
            dosya_say += 1
            metin = veri.decode("utf-8", "replace")
            b = tara_metin(metin)
            if b:
                sayac = {}
                for ad, _s, _e, deger in b:
                    sayac.setdefault(ad, []).append(deger)
                toplam[f] = sayac
    print(f"taranan metin dosyası: {dosya_say} · gizli değer içeren dosya: {len(toplam)}")
    ozet = {}
    for f, sayac in sorted(toplam.items()):
        satir = []
        for ad, ds in sayac.items():
            ozet[ad] = ozet.get(ad, 0) + len(ds)
            satir.append(f"{ad}×{len(ds)} (örn. {ds[0][:4]}…, uzunluk {len(ds[0])})")
        print(f"  {f}\n      " + "; ".join(satir))
    print("desen toplamları:", ozet)
    return toplam


def temizle(kaynak, hedef):
    sayi_d = sayi_g = 0
    for kok, _a, ds in os.walk(kaynak):
        for d in ds:
            s = os.path.join(kok, d)
            r = os.path.relpath(s, kaynak)
            h = os.path.join(hedef, r)
            os.makedirs(os.path.dirname(h), exist_ok=True)
            try:
                veri = open(s, "rb").read()
            except OSError:
                continue
            if ikili_mi(veri):
                shutil.copy2(s, h)
                continue
            metin = veri.decode("utf-8", "replace")
            b = tara_metin(metin)
            if b:
                # sondan başa değiştir
                for ad, bas, bit, _deger in sorted(b, key=lambda x: -x[1]):
                    metin = metin[:bas] + f"[GIZLI-SILINDI:{ad}]" + metin[bit:]
                sayi_g += len(b)
                sayi_d += 1
            open(h, "wb").write(metin.encode("utf-8"))
    print(f"temizlenen dosya: {sayi_d} · değiştirilen gizli değer: {sayi_g}")


if __name__ == "__main__":
    if len(sys.argv) >= 3 and sys.argv[1] == "tara":
        tara(sys.argv[2:])
    elif len(sys.argv) == 4 and sys.argv[1] == "temizle":
        temizle(sys.argv[2], sys.argv[3])
    else:
        print(__doc__)

tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

